export function renderCard(post) {
  const width = 1080, height = 1350;
  const data = Buffer.alloc(width * height * 4);
  const colors = { background:[12,17,19], ink:[238,243,234], accent:[177,236,120], muted:[151,168,163], line:[48,65,60] };
  function rect(x,y,w,h,color) {
    for(let yy=Math.max(0,y);yy<Math.min(height,y+h);yy++) for(let xx=Math.max(0,x);xx<Math.min(width,x+w);xx++) {const p=(yy*width+xx)*4; data[p]=color[0]; data[p+1]=color[1]; data[p+2]=color[2]; data[p+3]=255;}
  }
  function normalize(text) { return String(text).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[‘’]/g,"'").replace(/[–—]/g,'-').replace(/[“”]/g,'').toUpperCase(); }
  function text(value,x,y,scale,color) {
    for (const char of normalize(value)) {
      const glyph=FONT[char] || FONT['?'];
      for(let row=0;row<7;row++) for(let col=0;col<5;col++) if(glyph[row][col]==='1') rect(x+col*scale,y+row*scale,scale,scale,color);
      x+=6*scale;
    }
  }
  function wrap(value,maxChars) {
    const words=normalize(value).split(/\s+/); const lines=[];let line='';
    for(let word of words) { while(word.length>maxChars) { if(line){lines.push(line);line='';}lines.push(word.slice(0,maxChars));word=word.slice(maxChars); } if((line+' '+word).trim().length>maxChars){lines.push(line);line=word;}else line=(line+' '+word).trim(); }
    if(line)lines.push(line);return lines;
  }
  rect(0,0,width,height,colors.background);
  rect(72,72,936,4,colors.accent);
  text('WHILE YOU SLEEP',72,112,4,colors.accent);
  text('REAL AI PROJECTS. SMALL FIRST STEPS.',72,165,3,colors.muted);
  const title=wrap(post.title,19);let titleScale=8;
  if(title.length>4)titleScale=7;
  const titleLines=wrap(post.title,Math.floor(936/(6*titleScale)));
  let y=276;
  for(const line of titleLines.slice(0,5)){text(line,72,y,titleScale,colors.ink);y+=10*titleScale;}
  y+=40;
  for(const line of wrap(post.promise,31).slice(0,5)){text(line,72,y,5,colors.accent);y+=52;}
  rect(72,958,936,2,colors.line);
  text('THE AUTONOMOUS LOOP',72,1000,3,colors.muted);
  text('RESEARCH > PICK > WRITE > CHECK',72,1060,4,colors.ink);
  text('PUBLISH > MEASURE > IMPROVE',72,1110,4,colors.ink);
  text('SOURCE LINKS + YOUR FIRST 24 HOURS',72,1216,3,colors.muted);
  text('WHILE YOU SLEEP / SOURCE LINKS IN THE FEED',72,1258,3,colors.accent);
  return jpeg.encode({data,width,height},88).data;
}
